/**
 * Bounded Asynchronous Task Queue with Backpressure, Cancellation, and Graceful Shutdown
 * 
 * Features:
 * - Bounded capacity with backpressure (waits for space when full)
 * - Task cancellation support
 * - Graceful shutdown (drains pending tasks)
 * - Typed errors
 * - Deterministic behavior for testing
 */

// ============================================================================
// Types and Interfaces
// ============================================================================

export type TaskStatus = 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';

export interface TaskResult<T> {
  status: TaskStatus;
  value?: T;
  error?: Error;
  taskId: string;
}

export interface TaskOptions {
  /** Unique identifier for the task. If not provided, one will be generated. */
  id?: string;
  /** Priority of the task (lower number = higher priority). Default: 0 */
  priority?: number;
  /** Timeout in milliseconds. If exceeded, the task is cancelled. */
  timeout?: number;
  /** AbortSignal for external cancellation */
  signal?: AbortSignal;
}

export interface QueueOptions {
  /** Maximum number of tasks that can be queued (including running). Default: 100 */
  maxCapacity?: number;
  /** Maximum number of tasks that can run concurrently. Default: 1 */
  concurrency?: number;
  /** Default timeout for tasks in milliseconds. Default: undefined (no timeout) */
  defaultTimeout?: number;
  /** Whether to reject new tasks when queue is full instead of waiting. Default: false */
  rejectWhenFull?: boolean;
}

export interface QueueStats {
  pending: number;
  running: number;
  completed: number;
  failed: number;
  cancelled: number;
  totalEnqueued: number;
}

// ============================================================================
// Custom Errors
// ============================================================================

export class QueueError extends Error {
  constructor(message: string, public readonly code: string) {
    super(message);
    this.name = 'QueueError';
  }
}

export class QueueFullError extends QueueError {
  constructor(message = 'Queue is full') {
    super(message, 'QUEUE_FULL');
    this.name = 'QueueFullError';
  }
}

export class TaskCancelledError extends QueueError {
  constructor(taskId: string, message = `Task ${taskId} was cancelled`) {
    super(message, 'TASK_CANCELLED');
    this.name = 'TaskCancelledError';
    this.taskId = taskId;
  }
  public readonly taskId: string;
}

export class TaskTimeoutError extends QueueError {
  constructor(taskId: string, timeout: number, message?: string) {
    super(message || `Task ${taskId} timed out after ${timeout}ms`, 'TASK_TIMEOUT');
    this.name = 'TaskTimeoutError';
    this.taskId = taskId;
    this.timeout = timeout;
  }
  public readonly taskId: string;
  public readonly timeout: number;
}

export class QueueShutdownError extends QueueError {
  constructor(message = 'Queue is shutting down') {
    super(message, 'QUEUE_SHUTDOWN');
    this.name = 'QueueShutdownError';
  }
}

export class InvalidTaskError extends QueueError {
  constructor(message = 'Invalid task') {
    super(message, 'INVALID_TASK');
    this.name = 'InvalidTaskError';
  }
}

// ============================================================================
// Internal Task Representation
// ============================================================================

interface InternalTask<T> {
  id: string;
  priority: number;
  timeout?: number;
  signal?: AbortSignal;
  execute: () => Promise<T>;
  resolve: (result: TaskResult<T>) => void;
  reject: (error: Error) => void;
  status: TaskStatus;
  createdAt: number;
  startedAt?: number;
  completedAt?: number;
  abortController?: AbortController;
  timeoutId?: ReturnType<typeof setTimeout>;
  promise: Promise<TaskResult<T>>;
}

// ============================================================================
// Task Queue Implementation
// ============================================================================

